// === Tab: mySketch ===
var resolution = 1; //Default 1: The resoultion of the image produced; lower is more detailed but takes exponetially more time to load
var zoom = 350; //Default 350: How zoomed in the image is
var lineWidth = 1/400; //Default 1/400: The width of the lines
var heightIncrement = 1/30; //Default 1/30: How thick the bands are / how much space there is between the lines
var startHeight = 0.11; //Default 0.11: The start height/offset of the contour lines

var lines = true; //Default [starting value] true: Whether the lines are drawn. This can be toggled with any key.

var offset = startHeight;
var foo;

function setup() {
	createCanvas(windowWidth, windowHeight);
  noStroke();
	background(255);
	colorMode(HSB);

	if(!lines){
		offset = 0;
	}
	foo = new Array(floor(width/resolution));
	for (var i = 0; i < foo.length; i++) {
  	foo[i] = new Array(floor(height/resolution));
	}
}

function draw() {
	if(!lines || frameCount % 2 == 0){
		if(lines){
			offset += lineWidth;
		}else{
			offset += heightIncrement;
		}
		fill(map(offset,0.27,0.72,255,0),map(offset,0.25,1,50,255),map(offset,0.25,0.75,250,50));
	}else{
		offset += heightIncrement;
	}

	for(let x = 0; x < width; x += (Math.max(0.001, Math.abs(resolution)) || 1)){
		for(let y = 0; y < height; y += (Math.max(0.001, Math.abs(resolution)) || 1)){
			if(noise(x/zoom, y/zoom) < offset && foo[floor(x/resolution)][floor(y/resolution)] != true){
				foo[floor(x/resolution)][floor(y/resolution)] = true;
				if(!lines || frameCount % 2 == 0) rect(x, y, resolution, resolution);
			}
		}
	}
}

function mousePressed(){
	background(255);
	noiseSeed(random(10000));
	if(lines){
		offset = startHeight;
	}else{
		offset = 0;
	}
	foo = new Array(floor(width/resolution));
	for (var i = 0; i < foo.length; i++) {
  	foo[i] = new Array(floor(height/resolution));
	}
}

function keyPressed(){
	lines = !lines;
}
